def datatype_sql(self, expression: exp.DataType) -> str:
    if expression.is_type(exp.DataType.Type.ARRAY):
        if expression.expressions:
            values = self.expressions(expression, key="values", flat=True)
            return f"{self.expressions(expression, flat=True)}[{values}]"
        return "ARRAY"

    # FLOAT(p) is parsed as DOUBLE, but its precision must be preserved
    # in the generated SQL (DOUBLE PRECISION(p) is not equivalent).
    if expression.is_type(exp.DataType.Type.DOUBLE) and expression.expressions:
        expression = expression.copy()
        expression.set("this", "FLOAT")

    return super().datatype_sql(expression)
